package dev.riserecode;

import dev.riserecode.ui.clickgui.ClickGui;
import dev.riserecode.ui.component.*;
import dev.riserecode.ui.menu.*;
import dev.riserecode.cosmetics.*;
import dev.riserecode.setting.DoubleSetting;
import net.fabricmc.fabric.api.client.gametest.v1.context.ClientGameTestContext;
import net.minecraft.client.input.KeyEvent;
import java.nio.file.*;
import java.util.*;

/** Real native child workflows; acquisition uses a deterministic local provider, never live-network proof. */
public final class UxCompletionIntegrationTest {
    private static int checks;
    private static void check(boolean condition,String message){checks++;if(!condition)throw new AssertionError(message);}
    private static void press(ClientGameTestContext c,String text){c.runOnClient(mc->{var b=mc.gui.screen().children().stream().filter(v->v instanceof net.minecraft.client.gui.components.Button a&&a.getMessage().getString().equals(text)).map(net.minecraft.client.gui.components.Button.class::cast).findFirst().orElseThrow(()->new AssertionError("Missing "+text));check(b.active,"Action enabled: "+text);b.onPress(new KeyEvent(257,0,0));});c.waitTicks(3);}
    private static void action(ClientGameTestContext c,String label){c.runOnClient(mc->Client.INSTANCE.getClickGui().getActionButtons().stream().filter(b->b.label().equals(label)).findFirst().orElseThrow().activate());c.waitTicks(3);}
    public static void run(ClientGameTestContext c){
        c.waitFor(mc->Client.INSTANCE.isInitialized()&&Client.INSTANCE.resourcesReady()&&mc.gui.overlay()==null,1200);
        int[] original=c.computeOnClient(mc->new int[]{mc.getWindow().getScreenWidth(),mc.getWindow().getScreenHeight(),mc.options.guiScale().get()});c.getInput().resizeWindow(960,720);
        c.runOnClient(mc->{mc.options.guiScale().set(3);Client.INSTANCE.getThemeManager().reset();for(var pair:Map.of("Font Scale",2.0,"Window Width",360.0,"Window Height",240.0,"Content Padding",20.0).entrySet()){((DoubleSetting)Client.INSTANCE.getThemeManager().getSetting(pair.getKey())).setValue(pair.getValue());}var gui=Client.INSTANCE.getClickGui();gui.open(null);gui.selectPage(ClickGui.Page.COSMETICS);var e=gui.getCosmeticsEditor();e.select("pet-bee");e.search().setValue("zzzz no such item");});c.waitTicks(15);c.takeScreenshot("ux7-cosmetic-empty-font2");
        var draft=c.computeOnClient(mc->Client.INSTANCE.getClickGui().getCosmeticsEditor().draft());UxAuxiliaryIntegrationTest.focus(c,"Clear search, button");c.getInput().pressKey(257);c.waitTicks(4);c.runOnClient(mc->{var e=Client.INSTANCE.getClickGui().getCosmeticsEditor();check(e.search().getValue().isEmpty()&&e.draft().equals(draft),"Empty-state recovery clears visible query and retains draft");e.detailsButton().activate();});c.waitTicks(8);c.takeScreenshot("ux7-cosmetic-full-details-font2");
        c.runOnClient(mc->{check(mc.gui.screen() instanceof CosmeticDetailsScreen,"Compact action opens full acquisition and preview workflow");var d=(CosmeticDetailsScreen)mc.gui.screen();d.path().setValue("/missing/cape.png");});press(c,"Import PNG");c.waitTicks(5);c.takeScreenshot("ux7-cosmetic-import-failure-font2");
        Path png;byte[] pngBytes;try{var image=new java.awt.image.BufferedImage(64,32,java.awt.image.BufferedImage.TYPE_INT_ARGB);for(int y=0;y<32;y++)for(int x=0;x<64;x++)image.setRGB(x,y,0xFF24B8A4);var bytes=new java.io.ByteArrayOutputStream();javax.imageio.ImageIO.write(image,"PNG",bytes);image.flush();pngBytes=bytes.toByteArray();png=Files.createTempFile("ux-cape-",".png");Files.write(png,pngBytes);}catch(Exception e){throw new RuntimeException(e);}
        c.runOnClient(mc->((CosmeticDetailsScreen)mc.gui.screen()).path().setValue(png.toString()));press(c,"Import PNG");c.waitFor(mc->Client.INSTANCE.getClickGui().getCosmeticsEditor().selectedId().startsWith("import-"),400);c.runOnClient(mc->check(Client.INSTANCE.getClickGui().getCosmeticsEditor().draft().items().get(CosmeticCategory.CAPE).id().startsWith("import-"),"Native import selects validated PNG in draft"));press(c,"Back to outfit");c.runOnClient(mc->{check(mc.gui.screen()==Client.INSTANCE.getClickGui(),"Details returns to retained client");Client.INSTANCE.getClickGui().getCosmeticsEditor().discard();});
        Path fixture;try{fixture=Files.createTempDirectory("ux-acquisition-");var def=new CosmeticDefinition("ux-cape","Offline fixture cape",CosmeticCategory.CAPE,"cape","downloads/ux.png",CosmeticsLibrary.hash(pngBytes),pngBytes.length,"Test fixture","local","User supplied");Files.createDirectories(fixture.resolve("cosmetics"));var doc=new com.google.gson.JsonObject();doc.addProperty("version",1);doc.add("entries",new com.google.gson.Gson().toJsonTree(List.of(def)));Files.writeString(fixture.resolve("cosmetics/catalog.json"),doc.toString());}catch(Exception e){throw new RuntimeException(e);}
        var hold=new java.util.concurrent.atomic.AtomicBoolean(true);var fail=new java.util.concurrent.atomic.AtomicBoolean(false);
        var manager=c.computeOnClient(mc->new CosmeticsManager(fixture,(name,limit)->{while(hold.get()){Thread.sleep(5);}if(fail.get())throw new java.io.IOException("Offline fixture unavailable");return pngBytes;}));
        var editor=c.computeOnClient(mc->new CosmeticsEditor(manager,message->{}));c.runOnClient(mc->{editor.select("ux-cape");mc.gui.setScreen(new CosmeticDetailsScreen(Client.INSTANCE.getClickGui(),editor));});c.waitTicks(4);press(c,"Download / retry");c.runOnClient(mc->check(manager.library().busy(),"Acquisition starts without equipping unavailable draft"));press(c,"Cancel download");c.runOnClient(mc->check(!manager.library().busy()&&!manager.library().available(manager.library().find("ux-cape")),"Cancellation retains unavailable selection for retry"));hold.set(false);fail.set(true);press(c,"Download / retry");c.waitFor(mc->!manager.library().busy(),400);c.takeScreenshot("ux7-cosmetic-offline-download-failure-font2");c.runOnClient(mc->check(manager.library().status().contains("Offline fixture"),"Provider failure is visible without network"));fail.set(false);press(c,"Download / retry");c.waitFor(mc->!manager.library().busy(),400);c.runOnClient(mc->check(manager.library().available(manager.library().find("ux-cape")),"Retry validates and caches fixture asset"));press(c,"Select in draft");c.runOnClient(mc->{check(editor.draft().items().get(CosmeticCategory.CAPE).id().equals("ux-cape"),"Acquired asset can be selected in draft");editor.apply();check(manager.outfit().items().get(CosmeticCategory.CAPE).id().equals("ux-cape"),"Acquired draft applies independently of download");});press(c,"Back to outfit");c.runOnClient(mc->{manager.close();var gui=Client.INSTANCE.getClickGui();gui.showNotice("A long success message about the prior action remains readable without covering any current footer control.");gui.selectPage(ClickGui.Page.RESOURCES);});c.waitTicks(15);
        c.runOnClient(mc->{var gui=Client.INSTANCE.getClickGui();check(gui.getNoticeBounds().y()+gui.getNoticeBounds().height()<gui.getResourcesEditor().getBodyBounds().y(),"Message control occupies reserved header space above page actions");var b=gui.getNoticeBounds();gui.mouseClicked(new net.minecraft.client.input.MouseButtonEvent((b.centerX()-gui.getWindowBounds().centerX())*gui.getCanvasScale()+gui.getWindowBounds().centerX()*gui.getCanvasScale(),b.centerY()*gui.getCanvasScale(),new net.minecraft.client.input.MouseButtonInfo(0,0)),false);});c.waitTicks(3);
        c.runOnClient(mc->{check(mc.gui.screen() instanceof InfoScreen,"Message hit opens full text rather than a covered page action");check(((InfoScreen)mc.gui.screen()).text().contains("long success"),"Full long message remains available");});c.takeScreenshot("ux7-message-full-text-font2");c.runOnClient(mc->mc.gui.screen().onClose());c.waitTicks(4);c.takeScreenshot("ux7-message-clear-footer-font2");
        c.runOnClient(mc->{Client.INSTANCE.getClickGui().selectPage(ClickGui.Page.PROFILES);Client.INSTANCE.getClickGui().getSearchField().setValue("UxReplace");});c.waitTicks(5);
        for(boolean appearance:new boolean[]{false,true}){
            c.runOnClient(mc->{((DoubleSetting)Client.INSTANCE.getThemeManager().getSetting("Hover Duration")).setValue(.1);Client.INSTANCE.getModuleManager().getByClass(dev.riserecode.module.modules.FullBrightModule.class).orElseThrow().getBrightness().setValue(.1);});
            String button=appearance?"Save appearance profile":"Save client profile";action(c,button);
            var originalDocument=c.computeOnClient(mc->{try{return Files.readString(appearance?Client.INSTANCE.getConfigManager().getDirectory().resolve("theme-profiles/uxreplace.json"):Client.INSTANCE.getProfileManager().getFile("UxReplace"));}catch(Exception e){throw new RuntimeException(e);}});
            c.runOnClient(mc->{Client.INSTANCE.getClickGui().getSearchField().setValue(appearance?"UXREPLACE":"UxReplace");((DoubleSetting)Client.INSTANCE.getThemeManager().getSetting("Hover Duration")).setValue(.7);Client.INSTANCE.getModuleManager().getByClass(dev.riserecode.module.modules.FullBrightModule.class).orElseThrow().getBrightness().setValue(.7);});action(c,button);c.runOnClient(mc->check(mc.gui.screen() instanceof ProfileSaveScreen,"Duplicate profile opens explicit replacement decision"));c.getInput().pressKey(256);c.waitTicks(4);
            c.runOnClient(mc->{try{check(Files.readString(appearance?Client.INSTANCE.getConfigManager().getDirectory().resolve("theme-profiles/uxreplace.json"):Client.INSTANCE.getProfileManager().getFile("UxReplace")).equals(originalDocument),"Cancel preserves stored profile bytes");}catch(Exception e){throw new RuntimeException(e);}});
            action(c,button);c.runOnClient(mc->{var field=mc.gui.screen().children().stream().filter(net.minecraft.client.gui.components.EditBox.class::isInstance).map(net.minecraft.client.gui.components.EditBox.class::cast).findFirst().orElseThrow();field.setValue("UxCopy");});press(c,"Save as");
            c.runOnClient(mc->{check(appearance?Client.INSTANCE.getThemeManager().profileExists("UxCopy"):Files.exists(Client.INSTANCE.getProfileManager().getFile("UxCopy")),"Save as creates separate preset");Client.INSTANCE.getClickGui().getSearchField().setValue(appearance?"UXREPLACE":"UxReplace");});action(c,button);c.takeScreenshot("ux7-profile-replace-"+appearance);press(c,appearance?"Replace UXREPLACE":"Replace UxReplace");
            c.runOnClient(mc->check(appearance?Client.INSTANCE.getThemeManager().hasPreviousProfile("UxReplace"):Client.INSTANCE.getProfileManager().hasPrevious("UxReplace"),"Replacement preserves recovery version"));action(c,appearance?"Restore previous appearance: uxreplace":"Restore previous client: UxReplace");
            c.runOnClient(mc->{try{var restored=Files.readString(appearance?Client.INSTANCE.getConfigManager().getDirectory().resolve("theme-profiles/uxreplace.json"):Client.INSTANCE.getProfileManager().getFile("UxReplace"));check(com.google.gson.JsonParser.parseString(restored).equals(com.google.gson.JsonParser.parseString(originalDocument)),"Restore previous recovers original preset content");}catch(Exception e){throw new RuntimeException(e);}});
        }
        c.runOnClient(mc->Client.INSTANCE.openHudEditor());c.waitTicks(4);c.getInput().pressKey(72);c.waitTicks(4);c.runOnClient(mc->{check(mc.gui.screen() instanceof InfoScreen,"HUD exposes complete shortcut help");String help=((InfoScreen)mc.gui.screen()).text();check(help.contains("Ctrl+Shift")&&help.contains("Escape")&&help.contains("G:"),"Full help explains fine/coarse movement grid and save");});c.takeScreenshot("ux7-hud-full-help-font2");c.runOnClient(mc->{mc.gui.screen().onClose();mc.gui.screen().onClose();Client.INSTANCE.getThemeManager().reset();mc.gui.setScreen(null);});c.getInput().resizeWindow(original[0],original[1]);c.runOnClient(mc->mc.options.guiScale().set(original[2]));
        Client.INSTANCE.getLogger().info("UX completion workflow checks passed: {}",checks);
    }
}
